CREATE INDEX "idx_artworks_timeline_year_id" ON "met-galaxy_artwork" USING btree ((CASE WHEN "objectBeginDate" IS NULL THEN "objectEndDate" WHEN "objectEndDate" IS NULL THEN "objectBeginDate" ELSE floor((least("objectBeginDate", "objectEndDate") + greatest("objectBeginDate", "objectEndDate")) / 2.0)::integer END),"id") WHERE "met-galaxy_artwork"."imageAssetId" IS NOT NULL AND "met-galaxy_artwork"."localImageUrl" IS NOT NULL AND "met-galaxy_artwork"."localImageUrl" <> '';